import Foundation
final class RemoteBookRepository:BookRepository,@unchecked Sendable{let api:APIClient,cache:ReferenceCache;init(api:APIClient,cache:ReferenceCache){self.api=api;self.cache=cache}func list()async throws->[Book]{do{let page:Page<Book>=try await api.get("books");try await cache.save(page.items,kind:"book",bookId:nil);return page.items}catch{return try await cache.load(Book.self,kind:"book",bookId:nil)}}}
final class RemoteAccountRepository:AccountRepository,@unchecked Sendable{let api:APIClient,cache:ReferenceCache;init(api:APIClient,cache:ReferenceCache){self.api=api;self.cache=cache}func list(bookId:UUID)async throws->[Account]{do{let page:Page<Account>=try await api.get("accounts",query:[.init(name:"bookId",value:bookId.uuidString)]);try await cache.save(page.items,kind:"account",bookId:bookId);return page.items}catch{return try await cache.load(Account.self,kind:"account",bookId:bookId)}}}
